type World = { files: Map<string, string>; statuses: (string | undefined)[]; sid: string; denyRead: boolean; reads: string[] }

const FILE = '/s/statusline/sid1.json'
const T0 = Math.floor(tap.received_at) // epoch s of the fixture's tap
const NOW = (T0 + 1) * 1000 // ms: the tap is 1 s old
const START = { surface: 'terminal', isInteractive: true, cwd: '/work' } as const
const LINE = `5h ${tap.rate_limits.five_hour.used_percentage}% · 7d ${tap.rate_limits.seven_day.used_percentage}% · ctx ${tap.context_window.used_percentage}% · $${tap.cost.total_cost_usd.toFixed(2)}`

// Registers the stubs for all three mods (agent-status, team-band, usage-gauges). Call before the first `$` call.
function world(on: any, env: Record<string, string> = { TC_STATE: '/s' }): { w: World; clock: any } {
  const w: World = { files: new Map(), statuses: [], sid: 'sid1', denyRead: false, reads: [] }
  mock.env(on, env)
  const clock = mock.clock(on, { now: NOW })
  on('session.id', async () => ({ value: w.sid }))
  on('settings.read', () => ({ value: { permissions: {} } }))
  on('fs.write', ($: any, e: any) => { w.files.set(e.path, e.text); return { value: undefined } })
  on('fs.list', () => ({ value: [] }))
  on('fs.read', ($: any, e: any) => {
    w.reads.push(e.path)
    if (w.denyRead) throw new Error('denied')
    if (!w.files.has(e.path)) throw new Error('ENOENT')
    return { value: w.files.get(e.path) }
  })
  on('process.run', ($: any, e: any) => {
    const ok = (stdout = '') => ({ value: { exitCode: 0, stdout, stderr: '' } })
    if (e.argv[0] === 'id') return ok('503\n')
    return ok()
  })
  on('ui.status', ($: any, e: any) => { w.statuses.push(e.text); return { value: undefined } })
  on('session.start', () => ({ cwd: '/work' }))
  on('session.end', () => ({ sessionId: 'sid1' }))
  on('turn.start', () => ({ turnId: 't1' }))
  on('turn.complete', () => ({ text: 'done' }))
  on('tool.call', () => ({ result: 'ok' }))
  on('tool.check', () => ({ decision: 'allow' }))
  on('classic.PreToolUse', () => ({}))
  on('classic.PermissionRequest', () => ({}))
  on('classic.SessionStart', () => ({}))
  return { w, clock }
}

const putTap = (w: World, over: any = {}, path = FILE) => w.files.set(path, JSON.stringify({ ...tap, ...over }))

// ---- gaugeLine --------------------------------------------------------------------------------------------------

// mutation: build the line from the wrong keys or the wrong order -> 'the full line from the fixture' fails
test('gaugeLine: the full line from the fixture', () => {
  expect(gaugeLine(tap)).toBe(LINE)
  expect(LINE).toMatch(/^5h \d+% · 7d \d+% · ctx \d+% · \$\d+\.\d\d$/)
})

// mutation: always push the part (drop the pct(...) guard) -> the four 'left out' tests fail
test('gaugeLine: 5h is left out when missing', () => {
  const p: any = JSON.parse(JSON.stringify(tap)); delete p.rate_limits.five_hour
  expect(gaugeLine(p)).toBe(LINE.replace(/^5h \d+% · /, ''))
})
test('gaugeLine: 7d is left out when missing', () => {
  const p: any = JSON.parse(JSON.stringify(tap)); delete p.rate_limits.seven_day
  expect(gaugeLine(p)).toBe(LINE.replace(/ 7d \d+% ·/, ''))
})
test('gaugeLine: ctx is left out when missing', () => {
  const p: any = JSON.parse(JSON.stringify(tap)); delete p.context_window
  expect(gaugeLine(p)).toBe(LINE.replace(/ ctx \d+% ·/, ''))
})
test('gaugeLine: cost is left out when missing', () => {
  const p: any = JSON.parse(JSON.stringify(tap)); delete p.cost
  expect(gaugeLine(p)).toBe(LINE.replace(/ · \$\d+\.\d\d$/, ''))
})

// mutation: test only for presence, not typeof number -> this fails
test('gaugeLine: a non-number value is left out', () => {
  const p: any = JSON.parse(JSON.stringify(tap))
  p.rate_limits.five_hour.used_percentage = '40'
  p.cost.total_cost_usd = null
  expect(gaugeLine(p)).toBe(`7d ${tap.rate_limits.seven_day.used_percentage}% · ctx ${tap.context_window.used_percentage}%`)
})

test('gaugeLine: all missing is an empty string', () => {
  expect(gaugeLine({})).toBe('')
  expect(gaugeLine(null)).toBe('')
  expect(gaugeLine('x' as any)).toBe('')
})

// mutation: toFixed(1) or no toFixed -> this fails
test('gaugeLine: $ uses 2 decimals', () => {
  expect(gaugeLine({ cost: { total_cost_usd: 5.4901 } })).toBe('$5.49')
  expect(gaugeLine({ cost: { total_cost_usd: 0 } })).toBe('$0.00')
})

// mutation: Math.floor instead of Math.round -> this fails
test('gaugeLine: percentages use Math.round', () => {
  expect(gaugeLine({ context_window: { used_percentage: 61.5 } })).toBe('ctx 62%')
  expect(gaugeLine({ context_window: { used_percentage: 61.4 } })).toBe('ctx 61%')
})

// The clear is $.ui.status(undefined): a real run showed that '' (and ' ') leaves an empty `⚠ agent-board:` row, while
// undefined, null and no argument remove the row (tools/tests/e2e-usage-gauges.md, 'Clearing the status line').
// ---- timer ------------------------------------------------------------------------------------------------------

test('a status with the line after the first 10 s poll, none before', async ($, on) => {
  const { w, clock } = world(on)
  putTap(w)
  await $.session.start(START)
  await clock.advance(9000)
  expect(w.statuses).toEqual([])
  await clock.advance(1000)
  expect(w.statuses).toEqual([LINE])
  expect(w.reads).toContain(FILE)
})

// mutation: call ui.status on every poll (drop the last-shown comparison) -> this fails
test('no ui.status call when the line has not changed', async ($, on) => {
  const { w, clock } = world(on)
  putTap(w, { received_at: T0 + 100 })
  await $.session.start(START)
  await clock.advance(10000)
  await clock.advance(10000)
  await clock.advance(10000)
  expect(w.statuses).toEqual([LINE])
})

test('a changed line is shown again', async ($, on) => {
  const { w, clock } = world(on)
  putTap(w, { received_at: T0 + 100 })
  await $.session.start(START)
  await clock.advance(10000)
  putTap(w, { received_at: T0 + 100, cost: { total_cost_usd: 9.99 } })
  await clock.advance(10000)
  expect(w.statuses).toEqual([LINE, LINE.replace(/\$\d+\.\d\d$/, '$9.99')])
})

// mutation: keep the last text when the read fails (drop the catch -> '') -> this fails
test('a missing file clears the line', async ($, on) => {
  const { w, clock } = world(on)
  putTap(w, { received_at: T0 + 100 })
  await $.session.start(START)
  await clock.advance(10000)
  w.files.delete(FILE)
  await clock.advance(10000)
  expect(w.statuses).toEqual([LINE, undefined])
})

// mutation: drop the age check (secs(now) - p.received_at > STALE_S) -> this fails
test('a file older than 300 s clears the line', async ($, on) => {
  const { w, clock } = world(on)
  putTap(w) // received_at = T0, so it is 11 s old at the first poll
  await $.session.start(START)
  await clock.advance(10000)
  expect(w.statuses).toEqual([LINE])
  await clock.advance(300000) // the last poll runs at T0 + 311 s
  expect(w.statuses).toEqual([LINE, undefined])
})

// mutation: drop the session_id check -> this fails
test("another session's file clears the line", async ($, on) => {
  const { w, clock } = world(on)
  putTap(w, { received_at: T0 + 100 })
  await $.session.start(START)
  await clock.advance(10000)
  putTap(w, { received_at: T0 + 100, session_id: 'other' })
  await clock.advance(10000)
  expect(w.statuses).toEqual([LINE, undefined])
})

// mutation: drop the JSON.parse try/catch -> the poll throws and the line stays -> this fails
test('a file that does not parse clears the line', async ($, on) => {
  const { w, clock } = world(on)
  putTap(w, { received_at: T0 + 100 })
  await $.session.start(START)
  await clock.advance(10000)
  w.files.set(FILE, '{not json')
  await clock.advance(10000)
  expect(w.statuses).toEqual([LINE, undefined])
})

// mutation: read the id once at start instead of each poll -> this fails
test('a session id change reads the new id\'s file', async ($, on) => {
  const { w, clock } = world(on)
  putTap(w, { received_at: T0 + 100 })
  await $.session.start(START)
  await clock.advance(10000)
  w.sid = 'sid2'
  putTap(w, { received_at: T0 + 100, session_id: 'sid2', cost: { total_cost_usd: 1.5 } }, '/s/statusline/sid2.json')
  await clock.advance(10000)
  expect(w.reads).toContain('/s/statusline/sid2.json')
  expect(w.statuses.at(-1)).toBe(LINE.replace(/\$\d+\.\d\d$/, '$1.50'))
})

// mutation: drop the try/catch around the read -> the denied read throws out of the timer -> this fails
test('fs.read denied: no throw and the line is cleared', async ($, on) => {
  const { w, clock } = world(on)
  putTap(w, { received_at: T0 + 100 })
  await $.session.start(START)
  await clock.advance(10000)
  w.denyRead = true
  await clock.advance(10000)
  expect(w.statuses).toEqual([LINE, undefined])
})

test('TC_STATE unset: the file is read under TMPDIR/tmux-ctl-<uid>', async ($, on) => {
  const { w, clock } = world(on, { TMPDIR: '/var/t/' })
  await $.session.start(START)
  await clock.advance(10000)
  expect(w.reads).toContain('/var/t/tmux-ctl-503/statusline/sid1.json')
})

// mutation: cancel on every reason (drop the clear/resume exception) -> 'clear keeps polling' fails; never cancel -> 'other stops' fails
test('session.end (other) stops polling; clear and resume keep it', async ($, on) => {
  const { w, clock } = world(on)
  putTap(w, { received_at: T0 + 100 })
  await $.session.start(START)
  await clock.advance(10000)
  await $.session.end({ reason: 'clear', sessionId: 'sid1', resume: {} } as any)
  w.files.delete(FILE)
  await clock.advance(10000)
  expect(w.statuses).toEqual([LINE, undefined])
  await $.session.end({ reason: 'other', sessionId: 'sid1', resume: {} } as any)
  putTap(w, { received_at: T0 + 100 })
  const before = w.reads.length
  await clock.advance(30000)
  expect(w.reads.length).toBe(before)
})
